import { useState } from "react";
import NoteContext from "./noteContext";

const NoteState = (props) => {
  const host = "http://localhost:5000";
  const notesInitial = []

  const [notes, setNotes] = useState(notesInitial);

  //fetch a note
  const getNotes = async() => {
    try {
      const token = localStorage.getItem('token');
      console.log('Token from localStorage:', token); // Debug log
      
      if (!token) {
        console.error('No token found in localStorage');
        return;
      }

      console.log('Making request to fetch notes...'); // Debug log
      const response = await fetch(`${host}/api/notes/fetchallnotes`, {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
          "auth-token": token,
        }
      });
      
      console.log('Response status:', response.status); // Debug log
      console.log('Response ok:', response.ok); // Debug log
      
      const json = await response.json();
      console.log('Response data:', json); // Debug log
      
      // Check if the response is successful and contains an array
      if (response.ok && Array.isArray(json)) {
        setNotes(json);
        console.log('Notes set successfully:', json.length, 'notes'); // Debug log
      } else {
        console.error('Failed to fetch notes. Status:', response.status, 'Data:', json);
        setNotes([]); // Ensure notes remains an array
      }
    } catch (error) {
      console.error('Error fetching notes:', error);
      setNotes([]); // Ensure notes remains an array
    }
  }

  //Add a note
  const addNote = async(title, description, tag) => {
    try {
      const token = localStorage.getItem('token');
      console.log('Adding note with token:', token); // Debug log
      
      if (!token) {
        console.error('No token found for adding note');
        return;
      }

      const response = await fetch(`${host}/api/notes/addnote`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "auth-token": token,
        },
        body: JSON.stringify({title, description, tag}),
      });
      
      console.log('Add note response status:', response.status); // Debug log
      const note = await response.json();
      console.log('Add note response data:', note); // Debug log
      
      if (response.ok) {
        setNotes(prevNotes => prevNotes.concat(note));
        console.log('Note added successfully'); // Debug log
      } else {
        console.error('Failed to add note. Status:', response.status, 'Data:', note);
      }
    } catch (error) {
      console.error('Error adding note:', error);
    }
  };

  //Delete a Note
  const deleteNote = async(id) => {
    try {
      const token = localStorage.getItem('token');
      if (!token) {
        console.error('No token found for deleting note');
        return;
      }

      const response = await fetch(`${host}/api/notes/deletenote/${id}`, {
        method: "DELETE",
        headers: {
          "Content-Type": "application/json",
          "auth-token": token,
        }
      });
      
      console.log('Delete note response status:', response.status); // Debug log
      
      if (response.ok) {
        const newNotes = notes.filter((note) => {
          return note._id !== id;
        });
        setNotes(newNotes);
        console.log('Note deleted successfully'); // Debug log
      } else {
        const json = await response.json();
        console.error('Failed to delete note. Status:', response.status, 'Data:', json);
      }
    } catch (error) {
      console.error('Error deleting note:', error);
    }
  };

  //Update a note
  const editNote = async (id, title, description, tag) => {
    try {
      const token = localStorage.getItem('token');
      if (!token) {
        console.error('No token found for editing note');
        return;
      }

      const response = await fetch(`${host}/api/notes/updatenote/${id}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          "auth-token": token
        },
        body: JSON.stringify({title, description, tag}),
      });
      
      console.log('Edit note response status:', response.status); // Debug log
      
      if (response.ok) {
        let newNotes = JSON.parse(JSON.stringify(notes))
        //logic to edit in client
        for (let index = 0; index < newNotes.length; index++) {
          const element = newNotes[index];
          if (element._id === id) {
            newNotes[index].title = title;
            newNotes[index].description = description;
            newNotes[index].tag = tag;
            break;
          }
        }
        setNotes(newNotes);
        console.log('Note updated successfully'); // Debug log
      } else {
        const json = await response.json();
        console.error('Failed to update note. Status:', response.status, 'Data:', json);
      }
    } catch (error) {
      console.error('Error updating note:', error);
    }
  };

  return (
    <NoteContext.Provider value={{ notes, addNote, deleteNote, editNote, getNotes }}>
      {props.children}
    </NoteContext.Provider>
  );
};

export default NoteState;
